81	// ensureTrailWorktreeIgnoreRule appends the .entire/worktrees/ rule to an
82	// existing repo-root .gitignore when the directory isn't already ignored.
83	// Already ignored, or no .gitignore at all → silent no-op: the CLI doesn't
84	// impose ignore policy on a repo that hasn't opted into one, and committing
85	// the appended rule stays the user's choice.
86	func ensureTrailWorktreeIgnoreRule(ctx context.Context, w io.Writer, root string) error {
87		check := exec.CommandContext(ctx, "git", "check-ignore", "-q", trailWorktreesRelDir+"/")
88		check.Dir = root
89		err := check.Run()
90		if err == nil {
91			return nil
92		}
93		var exitErr *exec.ExitError
94		if !errors.As(err, &exitErr) || exitErr.ExitCode() != 1 {
95			return fmt.Errorf("failed to check ignore status of %s: %w", trailWorktreesRelDir, err)
96		}
97	
98		appended, err := appendIgnoreRule(filepath.Join(root, ".gitignore"))
99		if err != nil {
100			return err
101		}
102		if appended {
103			fmt.Fprintln(w, "Added .entire/worktrees/ to .gitignore — commit it to keep the rule.")
104		}
105		return nil
106	}
