108	func appendIgnoreRule(path string) (bool, error) {
109		const rule = trailWorktreesRelDir + "/"
110		content, err := os.ReadFile(path) //nolint:gosec // path derived from repo root / git common dir
111		if errors.Is(err, os.ErrNotExist) {
112			return false, nil
113		}
114		if err != nil {
115			return false, fmt.Errorf("failed to read %s: %w", path, err)
116		}
117		for line := range strings.SplitSeq(string(content), "\n") {
118			if strings.TrimSpace(line) == rule {
119				return false, nil
120			}
121		}
122		prefix := ""
123		if len(content) > 0 && !strings.HasSuffix(string(content), "\n") {
124			prefix = "\n"
125		}
126		updated := string(content) + prefix + rule + "\n"
127		if err := os.WriteFile(path, []byte(updated), 0o600); err != nil { //nolint:gosec // path derived from repo root / git common dir
128			return false, fmt.Errorf("failed to update %s: %w", path, err)
129		}
