170	// loadWorktreeIncludePatterns reads .worktreeinclude from root. A missing
171	// file means nothing gets copied. Lines are gitignore-style patterns; blank
172	// lines and #-comments are skipped.
173	func loadWorktreeIncludePatterns(root string) ([]string, error) {
174		data, err := os.ReadFile(filepath.Join(root, worktreeIncludeFile)) //nolint:gosec // path derived from repo root
175		if errors.Is(err, fs.ErrNotExist) {
176			return nil, nil
177		}
178		if err != nil {
179			return nil, fmt.Errorf("failed to read %s: %w", worktreeIncludeFile, err)
180		}
181		var patterns []string
182		for raw := range strings.SplitSeq(string(data), "\n") {
183			line := strings.TrimRight(raw, "\r")
184			if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
185				continue
186			}
187			patterns = append(patterns, line)
188		}
189		return patterns, nil
190	}
