192	// listIgnoredFiles returns untracked files ignored by repo ignore rules,
193	// relative to root. Paths under .entire/worktrees are excluded: sibling trail
194	// worktrees' own ignored files (e.g. their .env) appear in the listing at the
195	// main root and would otherwise be copied into every new worktree.
196	func listIgnoredFiles(ctx context.Context, root string) ([]string, error) {
197		cmd := exec.CommandContext(ctx, "git", "ls-files", "--others", "--ignored", "--exclude-standard", "-z")
198		cmd.Dir = root
199		output, err := cmd.Output()
200		if err != nil {
201			return nil, fmt.Errorf("failed to list ignored files: %w", err)
202		}
203		var files []string
204		for f := range bytes.SplitSeq(output, []byte{0}) {
205			if len(f) > 0 && !isManagedTrailWorktreePath(string(f)) {
206				files = append(files, string(f))
207			}
208		}
209		return files, nil
210	}
