212	func matchIncludePatterns(patterns, files []string) []string {
213		ps := make([]gitignore.Pattern, 0, len(patterns))
214		for _, pattern := range patterns {
215			ps = append(ps, gitignore.ParsePattern(pattern, nil))
216		}
217		matcher := gitignore.NewMatcher(ps)
218		included := make([]string, 0, len(files))
219		for _, file := range files {
220			rel, ok := cleanRelativeIncludeFile(file)
221			if !ok || !matcher.Match(strings.Split(filepath.ToSlash(rel), "/"), false) {
222				continue
223			}
224			included = append(included, rel)
225		}
226		return included
227	}
