245	// copyIncludedFile copies src into destRoot at rel. destRoot confines all
246	// writes to the worktree root, so a tracked symlinked directory in the
247	// branch cannot redirect the copy outside the worktree.
248	func copyIncludedFile(src string, destRoot *os.Root, rel string) error {
249		srcInfo, err := os.Lstat(src)
250		if err != nil {
251			return err //nolint:wrapcheck // lstat error is sufficient for caller context
252		}
253		if !srcInfo.Mode().IsRegular() {
254			return errors.New("source is not a regular file")
255		}
