257		if err != nil {
258			return err //nolint:wrapcheck // open error is sufficient for caller context
259		}
260		defer in.Close()
261		openedInfo, err := in.Stat()
262		if err != nil {
263			return err //nolint:wrapcheck // stat error is sufficient for caller context
264		}
265		if !openedInfo.Mode().IsRegular() || !os.SameFile(srcInfo, openedInfo) {
266			return errors.New("source changed while opening")
267		}
268		if err := osroot.MkdirAll(destRoot, filepath.Dir(rel), 0o750); err != nil {
