295	// checkoutTrailWorktree checks branch out into a managed worktree under
296	// <main-root>/.entire/worktrees instead of switching the current checkout.
297	// The final output line is a shell-safe `cd '<path>'` hint.
298	func checkoutTrailWorktree(ctx context.Context, w, errW io.Writer, branch string, force bool, trailNumber int) error {
299		// The trail number disambiguates the worktree directory: sanitized branch
300		// names are lossy (feature/x and feature-x collide), so an unnumbered
301		// trail cannot get a unique location.
302		if trailNumber <= 0 {
303			return fmt.Errorf("trail for branch %q has no number yet; cannot check out into a worktree", branch)
304		}
305		if err := ValidateBranchName(ctx, branch); err != nil {
306			return err
307		}
308	
309		root, err := trailWorktreeBaseRoot(ctx)
310		if err != nil {
311			return fmt.Errorf("failed to find main worktree root: %w", err)
312		}
313	
314		match, found, err := findWorktreeForBranch(ctx, branch, root)
315		if err != nil {
316			return err
317		}
318		if found {
319			// Lstat: a symlink planted at the registered path must not pass as a
320			// healthy worktree directory.
321			switch info, statErr := os.Lstat(match.path); {
322			case statErr == nil && !info.IsDir():
323				return fmt.Errorf("branch %q is registered to %s, which is not a directory", branch, match.path)
324			case statErr == nil:
325				if !match.managed {
326					return fmt.Errorf("branch %q is already checked out at %s", branch, match.path)
327				}
328				if err := validateTrailWorktreeReuse(ctx, match.path, branch); err != nil {
329					return staleTrailWorktreeError(branch, match.path)
330				}
331				printTrailWorktreeLocation(w, errW, "Worktree already exists at "+match.path, match.path)
332				return nil
333			case errors.Is(statErr, fs.ErrNotExist):
334				return staleTrailWorktreeError(branch, match.path)
335			default:
336				return fmt.Errorf("failed to check worktree at %s: %w", match.path, statErr)
337			}
338		}
339	
340		proceed, err := ensureTrailWorktreeBranchAvailable(ctx, errW, branch, force)
341		if err != nil {
342			return err
343		}
344		if !proceed {
345			fmt.Fprintf(errW, "Checkout of branch %s cancelled.\n", branch)
346			return nil
347		}
348	
349		if err := ensureTrailWorktreeIgnoreRule(ctx, errW, root); err != nil {
350			return err
351		}
352	
353		worktreePath := defaultTrailWorktreePath(root, branch, trailNumber)
354		if err := os.MkdirAll(filepath.Dir(worktreePath), 0o750); err != nil {
355			return fmt.Errorf("failed to create worktree parent: %w", err)
356		}
357		add := exec.CommandContext(ctx, "git", "worktree", "add", worktreePath, branch)
358		add.Dir = root
359		if output, err := add.CombinedOutput(); err != nil {
360			return fmt.Errorf("failed to create worktree: %s: %w", strings.TrimSpace(string(output)), err)
361		}
362	
363		if err := copyWorktreeIncludeFiles(ctx, errW, root, worktreePath); err != nil {
364			fmt.Fprintf(errW, "warning: could not copy %s files: %v\n", worktreeIncludeFile, err)
365		}
366	
367		printTrailWorktreeLocation(w, errW, "Worktree ready at "+worktreePath, worktreePath)
368		return nil
369	}
