371	// printTrailWorktreeLocation reports where the worktree lives. On a terminal
372	// it prints the note and a copy-paste cd hint. Otherwise stdout carries only
373	// the bare path — so `cd "$(entire trail checkout <n> --worktree)"` works —
374	// and the note goes to stderr.
375	func printTrailWorktreeLocation(w, errW io.Writer, note, path string) {
376		if interactive.IsTerminalWriter(w) {
377			fmt.Fprintln(w, note)
378			fmt.Fprintf(w, "cd %s\n", shellQuote(path))
379			return
380		}
381		fmt.Fprintln(errW, note)
382		fmt.Fprintln(w, path)
383	}
