385	func validateTrailWorktreeReuse(ctx context.Context, path, branch string) error {
386		expectedCommonDir, err := gitCommonDirForTrailWorktree(ctx)
387		if err != nil {
388			return err
389		}
390	
391		showTop := exec.CommandContext(ctx, "git", "-C", path, "rev-parse", "--show-toplevel")
392		output, err := showTop.Output()
393		if err != nil {
394			return err //nolint:wrapcheck // caller reports a prune hint, not this low-level probe
395		}
396		if normalizeWorktreePath(strings.TrimSpace(string(output))) != normalizeWorktreePath(path) {
397			return errors.New("path is not a worktree root")
398		}
399	
400		showCommon := exec.CommandContext(ctx, "git", "-C", path, "rev-parse", "--git-common-dir")
401		output, err = showCommon.Output()
402		if err != nil {
403			return err //nolint:wrapcheck // caller reports a prune hint, not this low-level probe
404		}
405		commonDir := strings.TrimSpace(string(output))
406		if !filepath.IsAbs(commonDir) {
407			commonDir = filepath.Join(path, commonDir)
408		}
409		if normalizeWorktreePath(commonDir) != normalizeWorktreePath(expectedCommonDir) {
410			return errors.New("path belongs to another repository")
411		}
412	
413		showBranch := exec.CommandContext(ctx, "git", "-C", path, "branch", "--show-current")
414		output, err = showBranch.Output()
415		if err != nil {
416			return err //nolint:wrapcheck // caller reports a prune hint, not this low-level probe
417		}
418		if strings.TrimSpace(string(output)) != branch {
419			return fmt.Errorf("worktree is not on branch %q", branch)
420		}
421		return nil
422	}
