424	// gitOutputError formats a failed git invocation, including git's stderr
425	// (captured by cmd.Output in ExitError.Stderr) when it carries a diagnostic —
426	// the bare error is usually just "exit status 128".
427	func gitOutputError(action string, err error) error {
428		var exitErr *exec.ExitError
429		if errors.As(err, &exitErr) && len(bytes.TrimSpace(exitErr.Stderr)) > 0 {
430			return fmt.Errorf("%s: %s: %w", action, bytes.TrimSpace(exitErr.Stderr), err)
431		}
432		return fmt.Errorf("%s: %w", action, err)
433	}
