439	// trailWorktreeMatch describes an existing worktree that has a branch checked
440	// out; managed means it lives under <root>/.entire/worktrees.
441	type trailWorktreeMatch struct {
442		path    string
443		managed bool
444	}
445	
446	// findWorktreeForBranch returns the worktree that has branch checked out,
447	// with found reporting whether any worktree does.
448	func findWorktreeForBranch(ctx context.Context, branch, root string) (match trailWorktreeMatch, found bool, err error) {
449		cmd := exec.CommandContext(ctx, "git", "worktree", "list", "--porcelain")
450		cmd.Dir = root
451		output, err := cmd.Output()
452		if err != nil {
453			return trailWorktreeMatch{}, false, gitOutputError("failed to list worktrees", err)
454		}
455		// Empty currentRoot: match any worktree, including the current checkout.
456		path, found := parseWorktreeForBranch(string(output), branch, "")
457		if !found {
458			return trailWorktreeMatch{}, false, nil
459		}
460		managedRoot := normalizeWorktreePath(filepath.Join(root, filepath.FromSlash(trailWorktreesRelDir)))
461		normalized := normalizeWorktreePath(path)
462		managed := normalized == managedRoot || strings.HasPrefix(normalized, managedRoot+string(filepath.Separator))
463		return trailWorktreeMatch{path: path, managed: managed}, true, nil
464	}
