466	// ensureTrailWorktreeBranchAvailable makes sure branch exists locally,
467	// fetching it from origin when it only exists there. It returns false when
468	// the user declined the fetch prompt. --force and non-interactive runs fetch
469	// without prompting.
470	func ensureTrailWorktreeBranchAvailable(ctx context.Context, w io.Writer, branch string, force bool) (bool, error) {
471		exists, err := BranchExistsLocally(ctx, branch)
472		if err != nil {
473			return false, fmt.Errorf("failed to check branch: %w", err)
474		}
475		if exists {
476			return true, nil
477		}
478	
479		remoteExists, err := BranchExistsOnRemote(ctx, branch)
480		if err != nil {
481			return false, fmt.Errorf("failed to check remote branch: %w", err)
482		}
483		if !remoteExists {
484			return false, fmt.Errorf("branch %q not found locally or on origin", branch)
485		}
486		if !force && interactive.CanPromptInteractively() {
487			shouldFetch, err := promptFetchFromRemote(branch)
488			if err != nil {
489				return false, err
490			}
491			if !shouldFetch {
492				return false, nil
493			}
494		}
495	
496		fmt.Fprintf(w, "Fetching branch '%s' from origin...\n", branch)
497		if err := fetchTrailWorktreeBranch(ctx, branch); err != nil {
498			return false, err
499		}
500		return true, nil
501	}
