503	// fetchTrailWorktreeBranch fetches origin's branch directly into refs/heads
504	// so `git worktree add` can check it out without touching the current
505	// checkout.
506	func fetchTrailWorktreeBranch(ctx context.Context, branch string) error {
507		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
508		defer cancel()
509	
510		refSpec := fmt.Sprintf("refs/heads/%s:refs/heads/%s", branch, branch)
511		// NoFilter: the worktree checkout needs full branch content; a partial
512		// clone would leave blobs missing.
513		output, err := remote.Fetch(ctx, remote.FetchOptions{
514			Remote:   "origin",
515			RefSpecs: []string{refSpec},
516			NoFilter: true,
517		})
518		if err != nil {
519			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
520				return errors.New("fetch timed out after 2 minutes")
521			}
522			return fmt.Errorf("failed to fetch branch from origin: %s: %w", strings.TrimSpace(string(output)), err)
523		}
524		return nil

use crate::api::schema::{
    WorktreeCreateParams, WorktreeListParams, WorktreeOpenParams, WorktreeRemoveParams,
};

// Worktree output is always JSON. The parsers retain `--json` as a hidden compatibility no-op.
pub(super) fn run_worktree_command(args: &[String]) -> std::io::Result<i32> {
    let Some(subcommand) = args.first().map(|arg| arg.as_str()) else {
        print_worktree_help();
        return Ok(2);
    };

    match subcommand {
        "list" => worktree_list(&args[1..]),
        "create" => worktree_create(&args[1..]),
        "open" => worktree_open(&args[1..]),
        "remove" => worktree_remove(&args[1..]),
        "help" | "--help" | "-h" => {
            print_worktree_help();
            Ok(0)
        }
        _ => {
            print_worktree_help();
            Ok(2)
        }
    }
}

fn worktree_list(args: &[String]) -> std::io::Result<i32> {
    let mut workspace_id = None;
    let mut cwd = None;

    let mut index = 0;
    while index < args.len() {
        match args[index].as_str() {
            "--workspace" => {
                let Some(value) = args.get(index + 1) else {
                    eprintln!("missing value for --workspace");
                    return Ok(2);
                };
                workspace_id = Some(super::normalize_workspace_id(value));
                index += 2;
            }
            "--cwd" => {
                let Some(value) = args.get(index + 1) else {
                    eprintln!("missing value for --cwd");
                    return Ok(2);
                };
                cwd = Some(normalize_path_arg(value)?);
                index += 2;
            }
            "--json" => index += 1,
            other => {
                eprintln!("unknown option: {other}");
                return Ok(2);
            }
        }
    }
    if workspace_id.is_some() && cwd.is_some() {
        eprintln!("usage: herdr worktree list [--workspace ID | --cwd PATH]");
        return Ok(2);
    }

    super::runtime::worktree_list(WorktreeListParams { workspace_id, cwd })
}

fn worktree_create(args: &[String]) -> std::io::Result<i32> {
